  assert_true(events.contains("readiness_unsupported"))
  assert_false(
    events.contains("\"stage\":\"orca-tunnel\",\"status\":\"retry\""),
  )
}

///|
async test "connection deadline expires without resetting after repeated checks" {
  let started = @env.now()
  let mut attempts = 0
  try {
    connection_timeout(started + 200, async fn() {
      while true {
        attempts += 1
        @async.sleep(25)
      }
    })
    assert_true(false)
  } catch {
    AdapterError(message) =>
      assert_true(message.contains("readiness timed out"))
    error => raise error
  }
  assert_true(attempts > 1)
  assert_true(@env.now() - started < 1000)
}

///|
async test "resume deadline returns failure while the worker continues recovering" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  @fs.write_file(
    directory + "/orca.yaml",
    "devsy: {connection: ssh, buildRef: refs/heads/main}\nenvironmentRecipes: [{id: test}]\n",
  )
  let (status, output, errors) = invoke("create", env, directory)
  assert_eq(status, 0, msg=errors)
  let result = @json.parse(output)
  let payload : Json = { "schemaVersion": 1, "recipeResult": result }
  let worker = required(field(result, "userData").unwrap(), "tunnelDirectory")
  defer ignore(invoke("destroy", env, directory, payload~))
  @fs.write_file(directory + "/rpc-unavailable", "")
  let started = @env.now()
  let (status, _, errors) = invoke("resume", env, directory, payload~)
  assert_true(status != 0)
  assert_true(errors.contains("readiness timed out after 60 seconds"))
  assert_true(@env.now() - started >= 59000)
  assert_true(@env.now() - started < 65000)
  assert_true(worker_alive(worker))
  assert_true(@fs.exists(directory + "/created"))
  @fs.remove(directory + "/rpc-unavailable")
  @async.with_timeout(35000, async fn() {
    while field(
            @json.parse(@fs.read_file(worker + "/status.json").text()),
            "status",
          ) !=
          Some(Json::string("connected")) {
      @async.sleep(100)
    }
  })
  assert_true(worker_alive(worker))
}

///|
fn command_failure(stage : String, status : Int32, detail : String) -> String {
  "\{stage} failed (exit \{status}); diagnostic run \{recording_run_id}:\n" +
  detail
}

///|
async fn command(
  program : String,
  args : Array[String],
  stage : String,
  environment? : Map[String, String],
) -> String {
  let (status, output, detail) = command_result(
    program,
    args,
    stage,
    environment?,
  )
  guard status == 0 else {
    raise AdapterError(command_failure(stage, status, detail))
  }
  output
}

///|
fn devsy_args(state : Json) -> Array[String] {
  let args = []
  for name in ["home", "context"] {
    if field(state, name) is Some(Json::String(value)) {
      args.push("--" + name)
      args.push(value)
    }
  }
  args
}

///|
async fn devsy_result(
  state : Json,
  args : Array[String],
  stage : String,
) -> (Int32, String, String) {
  let environment = @env.get_env_vars()
  for name in location_variables {
    match field(field(state, "devsyEnv").unwrap(), name) {
      Some(Json::String(value)) => environment.set(name, value)
      _ => environment.remove(name)
    }
  }
  let invocation = saved_command(state)
  let logging = if devsy_progress_stage(stage) {
    ["--log-level", "debug", "--log-output", "json"]
  } else {
    []
  }
  let result = command_result(
    invocation[0],
    invocation[1:].to_owned() + devsy_args(state) + logging + args,
    stage,
    environment~,
  )
  result
}

///|
async fn devsy(state : Json, args : Array[String], stage : String) -> String {
  let (status, output, detail) = devsy_result(state, args, stage)
  guard status == 0 else {
    raise AdapterError(command_failure(stage, status, detail))
  }
  output
}

///|
fn saved_command(state : Json) -> Array[String] raise ConfigError {
  command_field(state, "recipeResult.userData").unwrap_or(["devsy"])
}

///|
fn proxy(
  state : Json,
  executable : String,
  services~ : Bool = true,
  lease~ : String = "",
) -> String raise {
  let args = ["env"]
  for name in location_variables {
    args.push("-u")
    args.push(name)
  }
  for name in location_variables {
    if field(field(state, "devsyEnv").unwrap(), name)
      is Some(Json::String(value)) {
      args.push(name + "=" + value)
    }
  }
  (args +
  [executable, "--ssh-proxy", lease] +
  saved_command(state) +
  devsy_args(state) +
  [
    "workspace",
    "ssh",
    required(state, "workspaceId"),
    "--stdio",
    "--user",
    required(state, "user"),
  ] +
  (if services { [] } else { ["--start-services=false"] }))
  .map(quote)
  .join(" ")
  .replace_all(old="%", new="%%")
}

///|
async fn ssh_args(
  state : Json,
  services~ : Bool = true,
  lease~ : String = "",
) -> Array[String] {
  [
    "-o",
    "BatchMode=yes",
    "-o",
    "ConnectTimeout=15",
    "-o",
    "ProxyCommand=" + proxy(state, adapter_executable(), services~, lease~),
    "-o",
    "StrictHostKeyChecking=no",
    "-o",
    "UserKnownHostsFile=/dev/null",
    "-o",
    "LogLevel=ERROR",
    required(state, "user") + "@" + required(state, "workspaceId") + ".devsy",
  ]
}

